module matrix_recovery(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [3:0] m,\n    input [7:0] row_parity,\n    input [7:0] col_parity,\n    output reg [7:0] matrix_out [0:7],\n    output reg done,\n    output reg error\n);\n\n    // State definitions\n    localparam [2:0] IDLE      = 3'd0;\n    localparam [2:0] CHECK     = 3'd1;\n    localparam [2:0] INIT      = 3'd2;\n    localparam [2:0] FIX       = 3'd3;\n    localparam [2:0] DONE      = 3'd4;\n    localparam [2:0] ERROR     = 3'd5;\n\n    // Internal registers\n    reg [2:0] state, next_state;\n    reg [2:0] row_idx, col_idx;\n    reg [7:0] matrix [0:7];\n    reg [7:0] row_parity_check;\n    reg [7:0] col_parity_check;\n    reg [2:0] flip_count;\n    reg [2:0] flip_row, flip_col;\n\n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            error <= 1'b0;\n            row_idx <= 2'd0;\n            col_idx <= 2'd0;\n            flip_count <= 2'd0;\n            flip_row <= 2'd0;\n            flip_col <= 2'd0;\n            for (integer i = 0; i < 8; i = i + 1) begin\n                matrix[i] <= 8'd0;\n            end\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: begin\n                if (start) next_state = CHECK;\n            end\n            CHECK: begin\n                if (^row_parity[0+:8] != ^col_parity[0+:8])\n                    next_state = ERROR;\n                else\n                    next_state = INIT;\n            end\n            INIT: begin\n                if (row_idx < n) begin\n                    next_state = INIT;\n                end else begin\n                    next_state = FIX;\n                end\n            end\n            FIX: begin\n                if (row_idx < n && col_idx < m) begin\n                    next_state = FIX;\n                end else if (row_idx >= n && col_idx >= m) begin\n                    if (row_parity_check[0+:n] == row_parity[0+:n] &&\n                        col_parity_check[0+:m] == col_parity[0+:m])\n                        next_state = DONE;\n                    else\n                        next_state = ERROR;\n                end else begin\n                    next_state = FIX;\n                end\n            end\n            DONE, ERROR: begin\n                next_state = DONE;\n            end\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Main logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            done <= 1'b0;\n            error <= 1'b0;\n            row_idx <= 2'd0;\n            col_idx <= 2'd0;\n            flip_count <= 2'd0;\n            flip_row <= 2'd0;\n            flip_col <= 2'd0;\n            for (integer i = 0; i < 8; i = i + 1) begin\n                matrix[i] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                CHECK: begin\n                    row_parity_check <= 8'd0;\n                    col_parity_check <= 8'd0;\n                    row_idx <= 2'd0;\n                    col_idx <= 2'd0;\n                end\n                INIT: begin\n                    if (row_idx < n) begin\n                        if (col_idx < m) begin\n                            matrix[row_idx][col_idx] <= 1'b1;\n                            col_idx <= col_idx + 1;\n                        end else begin\n                            col_idx <= 2'd0;\n                            row_idx <= row_idx + 1;\n                        end\n                    end else begin\n                        row_idx <= 2'd0;\n                        col_idx <= 2'd0;\n                        for (integer i = 0; i < n; i = i + 1) begin\n                            row_parity_check[i] <= ^matrix[i][0+:m];\n                        end\n                        for (integer j = 0; j < m; j = j + 1) begin\n                            col_parity_check[j] <= ^{matrix[0][j], matrix[1][j], matrix[2][j], matrix[3][j],\n                                                      matrix[4][j], matrix[5][j], matrix[6][j], matrix[7][j]};\n                        end\n                    end\n                end\n                FIX: begin\n                    if (row_idx < n && col_idx < m) begin\n                        integer current_row = n - 1 - row_idx;\n                        integer current_col = m - 1 - col_idx;\n                        if (current_row >= 0 && current_col >= 0 &&\n                            row_parity_check[current_row] != row_parity[current_row] &&\n                            col_parity_check[current_col] != col_parity[current_col]) begin\n                            matrix[current_row][current_col] <= 1'b0;\n                            row_parity_check[current_row] <= ~row_parity_check[current_row];\n                            col_parity_check[current_col] <= ~col_parity_check[current_col];\n                        end\n                        if (col_idx < m - 1) begin\n                            col_idx <= col_idx + 1;\n                        end else begin\n                            col_idx <= 2'd0;\n                            row_idx <= row_idx + 1;\n                        end\n                    end else if (row_idx < n) begin\n                        row_idx <= row_idx + 1;\n                    end else if (col_idx < m) begin\n                        col_idx <= col_idx + 1;\n                    end\n                end\n                DONE: begin\n                    done <= 1'b1;\n                    error <= 1'b0;\n                    for (integer i = 0; i < 8; i = i + 1) begin\n                        matrix_out[i] <= matrix[i];\n                    end\n                end\n                ERROR: begin\n                    done <= 1'b1;\n                    error <= 1'b1;\n                    for (integer i = 0; i < 8; i = i + 1) begin\n                        matrix_out[i] <= 8'd0;\n                    end\n                end\n            endcase\n        end\n    end\nendmodule